  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); unit_propagate(list(Or(A, B), Or(Not(A), C), Or(Not(C), B), A), Not(A)) })), "[B, B | ~C, A]")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); unit_propagate(list(Or(A, B, C), Or(Not(B), C)), B) })), "[C]")
  expect_identical(.pyrun(local({ A <- Symbol("A"); B <- Symbol("B"); C <- Symbol("C"); D <- Symbol("D"); x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e"); unit_propagate(list(And(A, B), Or(Not(A), B)), A) })), "[A & B, B]")
