test_that("dimacs: doc_load matches SymPy", {
  expect_identical(.pyrun(local({ dimacs_load('1') })), "cnf_1")
  expect_identical(.pyrun(local({ dimacs_load('1 2') })), "cnf_1 | cnf_2")
  expect_identical(.pyrun(local({ dimacs_load('1 \n 2') })), "cnf_1 & cnf_2")
  expect_identical(.pyrun(local({ dimacs_load('1 2 \n 3') })), "cnf_3 & (cnf_1 | cnf_2)")
  expect_identical(.pyrun(local({ dimacs_load('c comment\np cnf 2 1\n-1 2 0\n') })), "cnf_2 | ~cnf_1")
  expect_identical(.pyrun(local({ dimacs_load('1 -2 0\n-1 2 0\n') })), "(cnf_1 | ~cnf_2) & (cnf_2 | ~cnf_1)")
  expect_identical(.pyrun(local({ dimacs_load('3 -1 2 0\n\n4') })), "cnf_4 & (cnf_2 | cnf_3 | ~cnf_1)")
  expect_identical(.pyrun(local({ dimacs_load('-5') })), "~cnf_5")
  expect_identical(.pyrun(local({ dimacs_load('1 x') })), "ERR ValueError: invalid literal for int() with base 10: 'x'")
})

test_that("dimacs: load_file matches SymPy", {
  expect_identical(.pyrun(local({ fn <- tempfile(fileext = '.cnf'); writeLines(c('c x', 'p cnf 3 2', '1 -3 0', '2 3 -1 0'), fn); dimacs_load_file(fn) })), "(cnf_1 | ~cnf_3) & (cnf_2 | cnf_3 | ~cnf_1)")
})

